<template><div class="office-page statistics-page" v-loading="loading"><div class="office-toolbar"><h2>统计与导出</h2><el-radio-group v-model="personal" @change="load"><el-radio-button :value="true">个人</el-radio-button><el-radio-button :value="false">团队</el-radio-button></el-radio-group><el-button @click="exportReport">导出报表</el-button></div><div class="metric-grid"><article v-for="m in metrics" :key="m.label"><span class="material-symbols-outlined">{{m.icon}}</span><span>{{m.label}}</span><strong>{{m.value}}</strong></article></div><section class="office-section"><h3>近 14 天活动</h3><div class="trend-bars"><div v-for="day in stats.trend||[]" :key="day.date" :title="`${day.date}：${day.edits} 次编辑，新增 ${day.newFileBytes} 字节`"><i :style="{height:Math.max(2,Number(day.edits)/maxEdits*120)+'px'}"></i><small>{{day.date.slice(5)}}</small></div></div><el-table :data="stats.trend||[]"><el-table-column prop="date" label="日期"/><el-table-column prop="edits" label="编辑次数"/><el-table-column label="新增文件存储"><template #default="{row}">{{bytes(row.newFileBytes)}}</template></el-table-column></el-table></section><section class="office-section"><h3>批量数据导出</h3><el-checkbox-group v-model="kinds"><el-checkbox value="documents">文档及编辑数据</el-checkbox><el-checkbox value="files">云盘原文件</el-checkbox><el-checkbox value="messages">会话记录</el-checkbox><el-checkbox value="tasks">任务</el-checkbox></el-checkbox-group><el-button type="primary" :loading="exporting" :disabled="!kinds.length" @click="exportData">下载 ZIP</el-button></section></div></template>
<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import axios from 'axios'
import request from '@/utils/request'
import {getToken} from '@/utils/token'
import {ElMessage} from 'element-plus'
const personal=ref(true),stats=ref<any>({}),loading=ref(false),exporting=ref(false),kinds=ref(['documents','tasks'])
const metrics=computed(()=>[{label:'文档',icon:'description',value:stats.value.documents||0},{label:'文件',icon:'folder',value:stats.value.files||0},{label:'存储用量',icon:'storage',value:bytes(stats.value.bytes||0)},{label:'已完成 / 任务',icon:'task_alt',value:`${stats.value.completed||0} / ${stats.value.tasks||0}`}]),maxEdits=computed(()=>Math.max(1,...(stats.value.trend||[]).map((d:any)=>Number(d.edits))))
function bytes(n:number){return n>=1048576?(n/1048576).toFixed(1)+' MB':n>=1024?(n/1024).toFixed(1)+' KB':n+' B'}
async function load(){loading.value=true;try{const r:any=await request.get('/user/workspace/statistics',{params:{personal:personal.value}});stats.value=r.data}catch{}finally{loading.value=false}}
function download(blob:Blob,name:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function exportReport(){const lines=['日期,编辑次数,新增文件字节',...(stats.value.trend||[]).map((d:any)=>`${d.date},${d.edits},${d.newFileBytes}`)];download(new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}),'工作空间统计.csv')}
async function exportData(){exporting.value=true;try{const r=await axios.get('/api/v1/user/workspace/export',{params:{personal:personal.value,kinds:kinds.value.join(',')},headers:{Authorization:'Bearer '+getToken(),'X-Space-Id':localStorage.getItem('active_space_id')||''},responseType:'blob',timeout:120000});if(String(r.headers['content-type']).includes('json'))throw new Error(JSON.parse(await r.data.text()).message||'导出失败');download(r.data,'工作空间数据.zip');ElMessage.success('导出完成')}catch(e:any){ElMessage.error(e.message||'导出失败')}finally{exporting.value=false}}
onMounted(load)
</script>
<style scoped>.statistics-page{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--space-6)}.statistics-page>section{min-width:0}.metric-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.metric-grid article{min-width:0;border:1px solid var(--c-border);border-radius:var(--radius-md);padding:16px;display:grid;gap:8px;background:var(--c-surface)}.metric-grid strong{font-size:26px;overflow-wrap:anywhere}.metric-grid .material-symbols-outlined{color:var(--c-brand)}.trend-bars{height:160px;display:flex;align-items:end;gap:6px;margin:16px 0;overflow:auto}.trend-bars>div{flex:1;min-width:32px;display:grid;justify-items:center;gap:6px}.trend-bars i{display:block;width:65%;background:var(--c-brand);border-radius:3px 3px 0 0}.trend-bars small{font-size:11px;color:var(--c-text-secondary)}@media(max-width:700px){.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
